/**
 * TextGlass — a word that writes itself on, one stroke at a time.
 *
 * ```tsx
 * <TextGlass word="hello" />
 * ```
 *
 * ## What is actually animated
 *
 * Each stroke is a dash pattern whose lit part grows from nothing to the whole
 * line: `strokeDasharray` moves, the path itself never changes. Two numbers a
 * frame rather than a rebuilt path, and the round cap stays pinned to the end
 * of the lit part for free — which is the pen nib, and the reason the line
 * reads as being laid down rather than uncovered.
 *
 * The whole word runs off one shared clock, and every stroke works out its own
 * slice of it. Nothing crosses back to React while it draws.
 *
 * ## Why the strokes are not evenly timed
 *
 * A stroke's share of the clock is proportional to how long its line is, so the
 * pen moves at one speed across the whole word. Splitting the time evenly
 * instead would race the pen through a dot and crawl it through an `l`, which
 * reads as a machine rather than a hand. `duration` scales the whole timeline
 * and the proportions hold.
 *
 * ## Reduced motion
 *
 * The finished word, drawn, immediately. A wordmark that never arrives is a
 * missing logo, so there is nothing to degrade to except its last frame.
 */
import { useCallback, useEffect, useMemo, useRef, type ReactNode } from 'react';
import { View, type ViewProps } from 'react-native';
import Animated, {
  Easing,
  cancelAnimation,
  runOnJS,
  useAnimatedProps,
  useAnimatedReaction,
  useReducedMotion,
  useSharedValue,
  withDelay,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import Svg, { Path } from 'react-native-svg';
import { useCSSVariable } from 'uniwind';
import { cn } from '@/lib/cn';
import { measurePath } from '@/components/ui/text-glass-path';
import { TEXT_GLASS_WORDS, writeWord, type TextGlassWord } from '@/components/ui/text-glass-glyphs';

export type { TextGlassWord } from '@/components/ui/text-glass-glyphs';

const AnimatedPath = Animated.createAnimatedComponent(Path);

/**
 * What one pen lift costs, in the same units as a stroke's length. The gap
 * between two strokes is time in which nothing is drawn, so it has to be
 * spent in the same currency as the drawing to keep the pen's speed even.
 */
const LIFT = 90;

/** How much of its own draw a stroke spends fading in. */
const FADE = 0.35;

/** Room left around the word for the stroke's own width and its round caps. */
const MARGIN = 1.1;

/** One stroke of a word, and the slice of the timeline it is drawn in. */
interface Stroke {
  d: string;
  length: number;
  start: number;
  end: number;
}

/** A path to draw, for a caller writing something the built-in words do not. */
export interface TextGlassStroke {
  /** The path data. Drawn in the order given, which is the order of writing. */
  d: string;
  /**
   * How long the line is, in the path's own units. Measured when it is left
   * out — pass it only for a path containing an arc, which is not measurable.
   */
  length?: number;
}

export interface TextGlassProps extends Omit<ViewProps, 'children'> {
  className?: string;
  /** Which built-in word to write. Ignored when `paths` is given. */
  word?: TextGlassWord;
  /**
   * Write something of your own instead of a built-in word. Needs `viewBox`,
   * since nothing else says what coordinates the paths are in.
   */
  paths?: TextGlassStroke[];
  /** The coordinate system `paths` are drawn in. Built-in words bring theirs. */
  viewBox?: string;
  /** How tall the word is, in points. Its width follows from the viewBox. */
  height?: number;
  /** Milliseconds for the whole word, pen lifts included. */
  duration?: number;
  /** Milliseconds of stillness before the first stroke. */
  delay?: number;
  /** Write it again, from nothing, forever. */
  loop?: boolean;
  /** False holds the word fully drawn instead of writing it. */
  enabled?: boolean;
  /** Ink colour. Defaults to the theme's foreground. */
  color?: string;
  /** Width of the line, in viewBox units. */
  strokeWidth?: number;
  /** Called once the last stroke lands. Not called on each pass of a loop. */
  onDone?: () => void;
}

/**
 * Lay the strokes out on a 0-to-1 timeline, each getting time in proportion to
 * its own length and a lift between one and the next.
 */
function schedule(lengths: number[]): { start: number; end: number }[] {
  const total = lengths.reduce((sum, length) => sum + length, 0);
  const span = total + LIFT * Math.max(0, lengths.length - 1);
  if (span <= 0) return lengths.map(() => ({ start: 0, end: 1 }));

  let travelled = 0;
  return lengths.map((length) => {
    const start = travelled / span;
    travelled += length;
    const end = travelled / span;
    travelled += LIFT;
    return { start, end };
  });
}

function TextGlassStrokeView({
  stroke,
  progress,
  color,
  strokeWidth,
  still,
}: {
  stroke: Stroke;
  progress: { value: number };
  color: string;
  strokeWidth: number;
  still: boolean;
}) {
  const { d, length, start, end } = stroke;

  const animated = useAnimatedProps(() => {
    const span = end - start;
    const raw = span > 0 ? (progress.value - start) / span : 1;
    const drawn = raw < 0 ? 0 : raw > 1 ? 1 : raw;
    return {
      // The lit part grows; the gap after it stays the whole line, so nothing
      // of the pattern repeats back into view at the end.
      strokeDasharray: [length * drawn, length],
      // Fading over the first part of the draw keeps the leading edge from
      // appearing as a hard dot out of nothing.
      strokeOpacity: drawn >= FADE ? 1 : drawn / FADE,
    };
  });

  if (still) {
    return (
      <Path
        d={d}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    );
  }

  return (
    <AnimatedPath
      animatedProps={animated}
      d={d}
      fill="none"
      stroke={color}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  );
}

export function TextGlass({
  className,
  word = 'hello',
  paths,
  viewBox,
  height = 80,
  duration,
  delay = 0,
  loop = false,
  enabled = true,
  color,
  strokeWidth = 15,
  onDone,
  accessibilityLabel,
  style,
  ...props
}: TextGlassProps): ReactNode {
  const inkToken = useCSSVariable('--color-foreground');
  const ink = color ?? (typeof inkToken === 'string' ? inkToken : '#0a0a0a');

  const reducedMotion = useReducedMotion();
  const still = reducedMotion || !enabled;

  const { strokes, box, span } = useMemo(() => {
    const source: TextGlassStroke[] = paths?.length
      ? paths
      : writeWord(TEXT_GLASS_WORDS[word]).map((d) => ({ d }));

    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    const lengths: number[] = [];
    for (const path of source) {
      const measured = measurePath(path.d);
      lengths.push(path.length ?? measured.length);
      if (measured.length > 0 || measured.maxX > measured.minX) {
        minX = Math.min(minX, measured.minX);
        minY = Math.min(minY, measured.minY);
        maxX = Math.max(maxX, measured.maxX);
        maxY = Math.max(maxY, measured.maxY);
      }
    }

    const windows = schedule(lengths);
    const drawn: Stroke[] = source.map((path, index) => ({
      d: path.d,
      length: lengths[index]!,
      start: windows[index]!.start,
      end: windows[index]!.end,
    }));

    const pad = strokeWidth * MARGIN;
    const measuredBox =
      minX === Infinity
        ? '0 0 1 1'
        : `${minX - pad} ${minY - pad} ${maxX - minX + pad * 2} ${maxY - minY + pad * 2}`;

    return {
      strokes: drawn,
      box: viewBox ?? measuredBox,
      // A longer word takes longer to write, unless a duration is asked for.
      span: duration ?? Math.round(900 + lengths.reduce((sum, l) => sum + l, 0) * 1.2),
    };
  }, [paths, word, viewBox, duration, strokeWidth]);

  const progress = useSharedValue(still ? 1 : 0);
  const done = useRef(false);

  const report = useCallback(() => {
    if (done.current) return;
    done.current = true;
    onDone?.();
  }, [onDone]);

  useEffect(() => {
    done.current = false;
    if (still) {
      progress.value = 1;
      return undefined;
    }
    progress.value = 0;
    const write = withTiming(1, { duration: span, easing: Easing.inOut(Easing.quad) });
    progress.value = withDelay(delay, loop ? withRepeat(write, -1, false) : write);
    return () => cancelAnimation(progress);
  }, [still, span, delay, loop, progress, strokes]);

  useAnimatedReaction(
    () => progress.value >= 1,
    (finished, was) => {
      if (finished && !was) runOnJS(report)();
    },
    [report]
  );

  const [, , boxWidth, boxHeight] = box.split(/\s+/).map(Number);
  const ratio = boxWidth && boxHeight ? boxWidth / boxHeight : 1;
  const width = Math.round(height * ratio);

  return (
    <View
      {...props}
      accessibilityRole="image"
      accessibilityLabel={accessibilityLabel ?? (paths?.length ? undefined : TEXT_GLASS_WORDS[word])}
      className={cn('items-start justify-center', className)}
      style={[{ width, height }, style]}
    >
      <Svg width={width} height={height} viewBox={box}>
        {strokes.map((stroke, index) => (
          <TextGlassStrokeView
            key={index}
            stroke={stroke}
            progress={progress}
            color={ink}
            strokeWidth={strokeWidth}
            still={still}
          />
        ))}
      </Svg>
    </View>
  );
}

TextGlass.displayName = 'TextGlass';

/**
 * The script alphabet TextGlass writes its built-in words with, and the rule
 * for joining letters into one continuous stroke.
 *
 * ## Why an alphabet rather than five finished wordmarks
 *
 * A word stored as one long path is a word that can only be corrected as a
 * whole: nudging the `a` in "Khalid" means re-authoring every curve after it,
 * because each one is positioned relative to the last. Storing letters instead
 * means a letter is fixed once and every word containing it improves.
 *
 * ## The join, which is what makes it read as handwriting
 *
 * Every letter is a run of **relative** cubics that starts and ends on the
 * join line, so its net displacement is exactly its own `advance` across and
 * nothing vertically. Concatenating two letters is therefore string
 * concatenation — one absolute `M` opens the word and every letter after it
 * continues the same stroke. A word is one unbroken line, the way a hand
 * writes it, rather than letters that happen to be adjacent.
 *
 * Ink that lifts off the page is stored apart from that run. `i` has its dot
 * and `t` its crossbar as `marks`; a capital is `detached` entirely. They
 * become their own strokes, drawn after the run they belong to — which is also
 * the order a hand writes them in.
 *
 * ## The frame
 *
 * `y = 0` is the join line. The baseline is `+15`, so letter bodies sit below
 * the joins and the connecting strokes rise between them — a flat join at the
 * very bottom of the letters would read as an underline. x-height is `-45`,
 * ascenders reach `-113` and capitals `-118`.
 *
 * A word-final letter may declare `final`, used in place of `run` when nothing
 * follows it. `o` needs it: its ordinary exit descends to the join line, and
 * with no letter after it to receive that stroke the shape closes into an `a`.
 */

/** One letter: how far it carries the pen, and the ink it lays down. */
export interface TextGlassGlyph {
  /** How far the pen advances, in frame units. Equals the run's own width. */
  advance: number;
  /** Relative cubics from the join line back to it, `advance` to the right. */
  run?: string;
  /** Used instead of `run` when the letter ends the word. */
  final?: string;
  /** Ink drawn after the run — a dot, a crossbar — at its own offset. */
  marks?: { x: number; y: number; d: string }[];
  /** A letter written without joining, as its own strokes. */
  detached?: { x: number; y: number; d: string }[];
}

/**
 * The letters the built-in words need. Adding a word means adding whatever it
 * is missing here; there is nothing else to update.
 */
export const TEXT_GLASS_GLYPHS: Record<string, TextGlassGlyph> = {
  a: { advance: 60, run: 'c 10 -12 22 -26 32 -36 c -4 -10 -17 -12 -26 -5 c -6 5 -8 20 -4 31 c 4 12 17 19 30 15 c 12 -5 16 -20 16 -46 c 1 20 2 40 4 56 c 2 6 4 5 8 -15' },
  c: { advance: 52, run: 'c 8 -17 19 -35 28 -41 c 5 -4 2 -12 -7 -11 c -14 2 -23 24 -19 43 c 4 16 16 26 32 22 c 7 0 12 -4 18 -13' },
  d: { advance: 58, run: 'c 8 -16 18 -34 27 -40 c 5 -4 2 -11 -7 -10 c -13 2 -22 23 -18 41 c 4 16 15 25 30 20 c 13 -6 18 -55 18 -124 c 0 -13 -3 -19 -5 -17 c -2 22 3 108 5 145 c 2 7 4 6 8 -15' },
  e: { advance: 58, run: 'c 6 -14 17 -30 26 -40 c 6 -7 3 -16 -6 -14 c -14 3 -22 22 -18 42 c 3 17 15 27 32 27 c 9 0 17 -5 24 -15' },
  h: { advance: 72, run: 'c 6 -30 18 -78 28 -106 c 4 -11 0 -18 -6 -14 c -6 4 -9 14 -8 26 c 2 24 5 76 8 109 c 3 -32 13 -58 27 -58 c 12 0 14 20 8 58 c 4 8 6 4 15 -15' },
  i: { advance: 44, run: 'c 6 -18 15 -36 22 -44 c 3 -4 5 -2 4 6 c -3 18 -5 36 -3 53 c 3 7 11 -1 21 -15', marks: [{x: 24,y: -68,d: 'c 3 -4 6 -1 3 3'}] },
  k: { advance: 70, run: 'c 6 -30 18 -76 28 -104 c 4 -11 0 -18 -6 -14 c -6 4 -9 14 -8 26 c 2 24 5 74 8 107 c 5 -24 17 -40 29 -48 c -12 8 -22 18 -27 27 c 8 5 17 12 25 21 c 5 4 11 2 21 -15' },
  l: { advance: 52, run: 'c 6 -30 18 -80 28 -108 c 4 -11 0 -18 -6 -14 c -6 4 -9 14 -8 26 c 2 24 6 78 10 111 c 3 8 14 6 28 -15' },
  m: { advance: 96, run: 'c 5 -28 12 -46 23 -46 c 10 0 13 20 8 61 c 2 -33 10 -61 21 -61 c 10 0 13 20 8 61 c 2 -33 10 -61 21 -61 c 10 0 13 20 8 61 c 2 5 0 2 7 -15' },
  n: { advance: 62, run: 'c 5 -28 12 -46 23 -46 c 10 0 13 20 8 61 c 2 -33 10 -61 21 -61 c 10 0 13 20 8 61 c 2 5 0 2 2 -15' },
  o: { advance: 68, run: 'c 7 -16 18 -34 27 -42 c 5 -5 2 -12 -7 -11 c -14 2 -23 24 -18 43 c 4 16 16 26 32 21 c 13 -4 19 -16 19 -32 c 0 -9 -2 -15 -5 -19 c 9 -2 14 3 16 12 c 2 6 3 12 4 28', final: 'c 7 -16 18 -34 27 -42 c 5 -5 2 -12 -7 -11 c -14 2 -23 24 -18 43 c 4 16 16 26 32 21 c 13 -4 19 -16 19 -32 c 0 -9 -2 -15 -5 -19 c 9 -1 14 2 16 8' },
  s: { advance: 50, run: 'c 8 -16 18 -32 25 -42 c 4 -6 0 -13 -8 -11 c -11 2 -16 12 -12 20 c 3 7 11 11 15 17 c 6 8 3 21 -8 24 c -6 2 3 7 13 6 c 9 -1 18 -5 25 -14' },
  t: { advance: 48, run: 'c 3 -26 8 -62 14 -86 c 2 -8 6 -12 8 -6 c 2 12 -5 74 -9 107 c 2 9 12 10 21 -3 c 5 -3 9 -7 14 -12', marks: [{x: 0,y: -54,d: 'c 15 -5 32 -7 44 -7'}] },
  w: { advance: 96, run: 'c 4 -26 10 -44 17 -46 c 6 16 11 40 15 61 c 3 -24 9 -46 16 -61 c 6 16 11 40 15 61 c 3 -24 9 -46 16 -61 c 3 14 9 32 17 46' },
  K: { advance: 78, detached: [{x: 10,y: -116,d: 'c -4 40 -8 88 -10 131'},{x: 62,y: -114,d: 'c -14 22 -30 42 -44 58 c 12 6 24 28 34 52 c 5 8 9 13 13 19'}] },
};

/**
 * Extra join between two letters. One knob for how tightly a word is set, and
 * a multiple of three so the cubic that carries it is written in whole numbers.
 */
const TRACKING = 9;

/** The words `word` selects, and the letters each is written with. */
export const TEXT_GLASS_WORDS = {
  hello: 'hello',
  khalid: 'Khalid',
  hi: 'hi',
  welcome: 'welcome',
  thanks: 'thanks',
} as const;

/** Which built-in word to write. */
export type TextGlassWord = keyof typeof TEXT_GLASS_WORDS;

/**
 * A word as the ordered strokes a hand would draw it in: the joined run first,
 * then the ink lifted off for it.
 */
export function writeWord(text: string): string[] {
  const strokes: string[] = [];
  const letters = [...text];
  let x = 0;
  let run: string | null = null;
  let pending: string[] = [];

  const lift = () => {
    if (run) strokes.push(run);
    run = null;
    strokes.push(...pending);
    pending = [];
  };

  for (let index = 0; index < letters.length; index += 1) {
    const glyph = TEXT_GLASS_GLYPHS[letters[index]!];
    if (!glyph) continue;

    if (glyph.detached) {
      lift();
      for (const stroke of glyph.detached) {
        strokes.push(`M ${x + stroke.x} ${stroke.y} ${stroke.d}`);
      }
      x += glyph.advance;
      continue;
    }

    if (run === null) {
      run = `M ${x} 0`;
    } else {
      run += ` c ${TRACKING / 3} 0 ${(TRACKING / 3) * 2} 0 ${TRACKING} 0`;
      x += TRACKING;
    }
    const finishes = index === letters.length - 1;
    run += ` ${finishes && glyph.final ? glyph.final : glyph.run}`;
    for (const mark of glyph.marks ?? []) {
      pending.push(`M ${x + mark.x} ${mark.y} ${mark.d}`);
    }
    x += glyph.advance;
  }

  lift();
  return strokes;
}

/**
 * Measuring an SVG path in JavaScript: how long its line is, and the box it
 * occupies.
 *
 * ## Why this exists
 *
 * The draw-on effect is a dash pattern whose lit part grows from nothing to
 * the whole line, and the pattern is written in the path's own units — so the
 * length of the line has to be a number before the first frame. The SVG
 * renderer knows it and will not say, and there is no measurement call to make
 * from JavaScript. Hardcoding a length per stroke would work for the built-in
 * words and break the moment somebody passed a path of their own, which is the
 * case the escape hatch exists for.
 *
 * The box comes from the same walk. A caller who supplies paths but no
 * `viewBox` would otherwise have to work one out by hand.
 *
 * ## How
 *
 * Curves are flattened into short line segments and the segments are summed.
 * `SEGMENTS` sets how short: 24 pieces per curve is well inside a rounding
 * error at the sizes a wordmark is drawn at, and the walk happens once per
 * path rather than once per frame.
 *
 * Arcs (`A`/`a`) are not implemented — nothing in the alphabet needs one, and
 * a wrong length is worse than a refusal. A path containing one measures only
 * the rest of itself, so pass `length` alongside it.
 */

/** Pieces each curve is flattened into before its length is summed. */
const SEGMENTS = 24;

/** What a path occupies, and how far the pen travels drawing it. */
export interface PathMeasurement {
  /** Total length of the line, in the path's own units. */
  length: number;
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

/** Every number in a command's arguments, in order. */
function numbersOf(source: string): number[] {
  const out: number[] = [];
  const re = /-?\d*\.?\d+(?:e[-+]?\d+)?/gi;
  let match = re.exec(source);
  while (match) {
    out.push(Number(match[0]));
    match = re.exec(source);
  }
  return out;
}

function cubic(t: number, a: number, b: number, c: number, d: number): number {
  const u = 1 - t;
  return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d;
}

function quadratic(t: number, a: number, b: number, c: number): number {
  const u = 1 - t;
  return u * u * a + 2 * u * t * b + t * t * c;
}

/**
 * Walk a path, summing the distance travelled and tracking the box.
 *
 * A subpath's `Z` closes it back to where that subpath opened, which counts
 * towards the length like any other line — a closed shape that stopped short
 * of its own start would draw with a gap in it.
 */
export function measurePath(d: string): PathMeasurement {
  let length = 0;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;

  // Where the pen is, where the current subpath opened, and the reflection of
  // the last curve's trailing control point — what `S` and `T` continue from.
  let x = 0;
  let y = 0;
  let startX = 0;
  let startY = 0;
  let lastControlX = 0;
  let lastControlY = 0;
  let lastCurve = '';

  const see = (px: number, py: number) => {
    if (px < minX) minX = px;
    if (px > maxX) maxX = px;
    if (py < minY) minY = py;
    if (py > maxY) maxY = py;
  };

  const lineTo = (px: number, py: number) => {
    length += Math.hypot(px - x, py - y);
    x = px;
    y = py;
    see(x, y);
  };

  for (const token of d.match(/[a-z][^a-z]*/gi) ?? []) {
    const command = token[0]!;
    const upper = command.toUpperCase();
    const relative = command !== upper;
    const args = numbersOf(token.slice(1));
    // How many numbers one repetition of this command consumes. A command may
    // carry several sets — `c` with twelve numbers is two curves.
    const arity =
      upper === 'M' || upper === 'L' || upper === 'T'
        ? 2
        : upper === 'H' || upper === 'V'
          ? 1
          : upper === 'C'
            ? 6
            : upper === 'S' || upper === 'Q'
              ? 4
              : 0;

    if (upper === 'Z') {
      lineTo(startX, startY);
      lastCurve = '';
      continue;
    }
    if (!arity) continue;

    for (let at = 0; at + arity <= args.length; at += arity) {
      const set = args.slice(at, at + arity);
      const dx = relative ? x : 0;
      const dy = relative ? y : 0;

      if (upper === 'M') {
        // Only the first pair of an `M` moves; the rest are implicit lines.
        x = set[0]! + dx;
        y = set[1]! + dy;
        if (at === 0) {
          startX = x;
          startY = y;
          see(x, y);
        } else {
          length += Math.hypot(x - dx, y - dy);
          see(x, y);
        }
        lastCurve = '';
        continue;
      }
      if (upper === 'L') {
        lineTo(set[0]! + dx, set[1]! + dy);
        lastCurve = '';
        continue;
      }
      if (upper === 'H') {
        lineTo(set[0]! + dx, y);
        lastCurve = '';
        continue;
      }
      if (upper === 'V') {
        lineTo(x, set[0]! + dy);
        lastCurve = '';
        continue;
      }

      const fromX = x;
      const fromY = y;
      let c1x: number;
      let c1y: number;
      let c2x: number;
      let c2y: number;
      let toX: number;
      let toY: number;

      if (upper === 'C') {
        c1x = set[0]! + dx;
        c1y = set[1]! + dy;
        c2x = set[2]! + dx;
        c2y = set[3]! + dy;
        toX = set[4]! + dx;
        toY = set[5]! + dy;
      } else if (upper === 'S') {
        const mirrored = lastCurve === 'C';
        c1x = mirrored ? 2 * x - lastControlX : x;
        c1y = mirrored ? 2 * y - lastControlY : y;
        c2x = set[0]! + dx;
        c2y = set[1]! + dy;
        toX = set[2]! + dx;
        toY = set[3]! + dy;
      } else {
        // Q and T are quadratic: one control point, raised to a cubic below.
        const qx = upper === 'Q' ? set[0]! + dx : lastCurve === 'Q' ? 2 * x - lastControlX : x;
        const qy = upper === 'Q' ? set[1]! + dy : lastCurve === 'Q' ? 2 * y - lastControlY : y;
        toX = upper === 'Q' ? set[2]! + dx : set[0]! + dx;
        toY = upper === 'Q' ? set[3]! + dy : set[1]! + dy;
        lastControlX = qx;
        lastControlY = qy;
        lastCurve = 'Q';
        let prevX = fromX;
        let prevY = fromY;
        for (let step = 1; step <= SEGMENTS; step += 1) {
          const t = step / SEGMENTS;
          const px = quadratic(t, fromX, qx, toX);
          const py = quadratic(t, fromY, qy, toY);
          length += Math.hypot(px - prevX, py - prevY);
          see(px, py);
          prevX = px;
          prevY = py;
        }
        x = toX;
        y = toY;
        continue;
      }

      let prevX = fromX;
      let prevY = fromY;
      for (let step = 1; step <= SEGMENTS; step += 1) {
        const t = step / SEGMENTS;
        const px = cubic(t, fromX, c1x, c2x, toX);
        const py = cubic(t, fromY, c1y, c2y, toY);
        length += Math.hypot(px - prevX, py - prevY);
        see(px, py);
        prevX = px;
        prevY = py;
      }
      x = toX;
      y = toY;
      lastControlX = c2x;
      lastControlY = c2y;
      lastCurve = 'C';
    }
  }

  if (minX === Infinity) {
    return { length: 0, minX: 0, minY: 0, maxX: 0, maxY: 0 };
  }
  return { length, minX, minY, maxX, maxY };
}
